INSERT IGNORE INTO dart_financial_statement (
    corp_code, stock_code, business_year, report_code,
    statement_type, account_id, account_name, amount, currency, raw_json
) VALUES (
    #{corpCode}, #{stockCode}, #{businessYear}, #{reportCode},
    #{statementType}, #{accountId}, #{accountName}, #{amount}, #{currency},
    #{rawJson}
)

mapper.select:
SELECT id, corp_code, stock_code, business_year, report_code,
       statement_type, account_id, account_name, amount, currency, created_at
FROM dart_financial_statement
WHERE stock_code = #{stockCode}
ORDER BY business_year DESC, report_code DESC
LIMIT #{limit}

SELECT id, corp_code, stock_code, business_year, report_code,
       statement_type, account_id, account_name, amount, currency, created_at
FROM dart_financial_statement
WHERE corp_code = #{corpCode}
  AND business_year = #{businessYear}
  AND report_code = #{reportCode}
ORDER BY account_name
